from __future__ import annotations

# AUTO-GENERATED MATCHER SHIM (REQ-003-007)
# Matcher: 'Bash(git push*)'
# Generated by build/scripts/generate_hooks.py (REQ-003-007).
# DO NOT EDIT BY HAND - regenerated on every build. Apply NO-REGEN
# sentinel ("# NO-REGEN" or sidecar .noregen) to opt out.
import os as _os
import sys as _sys
import io as _io
import json as _json
import re as _re
import fnmatch as _fnmatch

_MATCHER = 'Bash(git push*)'

# Bound the standalone shim read before JSON parsing so a malicious or buggy
# upstream cannot cause unbounded allocation (CWE-400).
_HOOK_STDIN_CEILING_BYTES = 64 * 1024 * 1024

# Apply the normal payload policy only after matcher selection. Multi-call
# events can contain a large unrelated call that must not deny a small matched
# call.
_MATCHED_SHIM_PAYLOAD_LIMIT_BYTES = 2 * 1024 * 1024
_MAX_MATCHER_TOOL_CALLS = 256


def _shim_classify(pattern):
    # MIRROR: classify_matcher (build-time, build/scripts/generate_hooks.py)
    # and _shim_classify (runtime, this inlined copy) MUST agree on the
    # grammar. Update both when the grammar changes.
    if pattern.startswith("^") and pattern.endswith("$"):
        return "regex", {"pattern": pattern}
    m = _re.match(r"^([A-Za-z_][A-Za-z0-9_]*)\((.*)\)$", pattern)
    if m:
        return "tool-glob", {"toolName": m.group(1), "argsGlob": m.group(2)}
    return "bare", {"toolName": pattern}


def _shim_normalize_args(tool_args):
    r"""Stringify and whitespace-normalize tool_input for fnmatch comparison.

    REQ-003-007: collapse \s+ to a single space and strip ends. Pattern
    is NOT normalized; authors write patterns assuming single spaces.
    """
    if isinstance(tool_args, dict):
        # Bash hooks place command under "command"; keep this fallback
        # path narrow but correct for the live corpus.
        cmd = tool_args.get("command")
        if isinstance(cmd, str):
            text = cmd
        else:
            text = _json.dumps(tool_args, sort_keys=True)
    elif isinstance(tool_args, str):
        text = tool_args
    elif tool_args is None:
        text = ""
    else:
        text = str(tool_args)
    return _re.sub(r"\s+", " ", text).strip()


def _shim_glob_match(args_glob, tool_args_norm):
    """Match each top-level `|` branch as a separate glob alternative."""
    branches = args_glob.split("|") if args_glob else [""]
    for branch in branches:
        if _fnmatch.fnmatchcase(tool_args_norm, branch):
            return True
    return False


def _shim_unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON object key")
        result[key] = value
    return result


def _shim_load_json(raw_value):
    return _json.loads(raw_value, object_pairs_hook=_shim_unique_object)


def _shim_parse_json_string(raw_value, field_name):
    if isinstance(raw_value, str):
        stripped = raw_value.lstrip()
        if not stripped or stripped[0] not in "{[\"":
            return raw_value
        try:
            return _shim_load_json(raw_value)
        except _json.JSONDecodeError as exc:
            print(
                "matcher-shim [{}]: {} is not valid JSON: {}".format(
                    _MATCHER, field_name, exc
                ),
                file=_sys.stderr,
            )
            return raw_value
    return raw_value


def _shim_tool_input_from_call_args(raw_args):
    return _shim_parse_json_string(raw_args, "toolCalls.args")


def _shim_validate_tool_name(name, field):
    if not isinstance(name, str) or not name.strip():
        raise ValueError("{} must be a non-empty string".format(field))
    if name != name.strip():
        raise ValueError(
            "{} must not have leading or trailing whitespace".format(field)
        )
    return name


def _shim_json_equal(left, right):
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return left.keys() == right.keys() and all(
            _shim_json_equal(left[key], right[key]) for key in left)
    if isinstance(left, list):
        return len(left) == len(right) and all(
            _shim_json_equal(a, b) for a, b in zip(left, right))
    return left == right


def _shim_alias_value(payload, snake, camel, parser=None):
    fields = [field for field in (snake, camel) if field in payload]
    if not fields:
        return False, None, snake, False
    values = [payload[field] for field in fields]
    if parser is not None:
        values = [parser(value, field) for value, field in zip(values, fields)]
    if len(values) == 2 and not _shim_json_equal(values[0], values[1]):
        raise ValueError(
            "conflicting top-level {}/{} values".format(snake, camel)
        )
    changed = fields != [snake] or values[0] != payload[snake]
    return True, values[0], "/".join(fields), changed


def _shim_top_level_candidate(payload):
    has_name, name, _, name_changed = _shim_alias_value(
        payload, "tool_name", "toolName", _shim_validate_tool_name
    )
    if not has_name:
        raise ValueError("hook input missing string `tool_name`/`toolName` field")
    input_payload = payload
    if payload.get("tool_input") is None and "toolArgs" in payload:
        input_payload = {key: value for key, value in payload.items() if key != "tool_input"}
    has_input, tool_input, input_field, input_changed = _shim_alias_value(
        input_payload, "tool_input", "toolArgs", _shim_parse_json_string
    )
    has_call_id, call_id, _, call_id_changed = _shim_alias_value(
        payload, "tool_call_id", "toolCallId"
    )
    if not (name_changed or input_changed or call_id_changed):
        return payload, input_field
    candidate = dict(payload)
    for field in ("toolName", "toolArgs", "toolCallId"):
        candidate.pop(field, None)
    candidate["tool_name"] = name
    if has_input:
        candidate["tool_input"] = tool_input
    if has_call_id:
        candidate["tool_call_id"] = call_id
    return candidate, input_field


def _shim_candidate_payloads(payload):
    if "toolCalls" in payload:
        tool_calls = payload["toolCalls"]
        if not isinstance(tool_calls, list):
            raise ValueError("toolCalls must be a list when present")
        if len(tool_calls) > _MAX_MATCHER_TOOL_CALLS:
            raise ValueError(
                "toolCalls contains {} entries; limit is {}".format(
                    len(tool_calls), _MAX_MATCHER_TOOL_CALLS
                )
            )
        # A payload may carry top-level action fields OR a `toolCalls` batch,
        # never both: the host precedence contract between the two shapes is
        # unverified, so a top-level Read alongside a Bash in `toolCalls` is
        # ambiguous. Reject any mix (empty or non-empty batch) before a guard
        # ever sees a candidate (#3200).
        conflicting = [
            field
            for field in (
                "tool_name",
                "toolName",
                "tool_input",
                "toolArgs",
                "tool_call_id",
                "toolCallId",
            )
            if field in payload
        ]
        if conflicting:
            raise ValueError(
                "toolCalls conflicts with top-level action fields: "
                + ", ".join(conflicting)
            )
        for index, call in enumerate(tool_calls):
            if not isinstance(call, dict):
                raise ValueError(
                    "toolCalls[{}] must be an object".format(index)
                )
            _shim_validate_tool_name(
                call.get("name"), "toolCalls[{}].name".format(index)
            )
        for call in tool_calls:
            name = call["name"]
            candidate = dict(payload)
            for field in (
                "toolCalls",
                "tool_name",
                "toolName",
                "tool_input",
                "toolArgs",
                "tool_call_id",
                "toolCallId",
            ):
                candidate.pop(field, None)
            candidate["tool_name"] = name
            candidate["tool_input"] = _shim_tool_input_from_call_args(call.get("args"))
            if "id" in call:
                candidate["tool_call_id"] = call.get("id")
            yield candidate, "toolCalls.args"
        return
    yield _shim_top_level_candidate(payload)


def _shim_match_candidate(payload, kind, params):
    tool_name = payload.get("tool_name")
    if not isinstance(tool_name, str):
        raise ValueError("hook input missing string `tool_name`/`toolName` field")
    if kind == "regex":
        return _re.fullmatch(params["pattern"], tool_name) is not None
    if kind == "tool-glob":
        if tool_name != params["toolName"]:
            return False
        norm_args = _shim_normalize_args(payload.get("tool_input"))
        return _shim_glob_match(params["argsGlob"], norm_args)
    return tool_name == params["toolName"]


def _shim_select_payloads(payload):
    kind, params = _shim_classify(_MATCHER)
    for candidate, input_field in _shim_candidate_payloads(payload):
        if _shim_match_candidate(candidate, kind, params):
            yield candidate, input_field


def _shim_replay_bytes(payload, selected, raw):
    if selected is payload:
        return raw
    return _json.dumps(selected, separators=(",", ":")).encode("utf-8")


def _shim_exit_code(exc):
    code = exc.code
    if code is None:
        return 0
    if isinstance(code, int):
        return code
    return 1


def _shim_invoke_selection(payload, selection, raw):
    selected, input_field = selection
    replay = _shim_replay_bytes(payload, selected, raw)
    if len(replay) > _MATCHED_SHIM_PAYLOAD_LIMIT_BYTES:
        print(
            (
                "matcher-shim [{}]: matched replay from {} exceeds "
                "{} bytes; refusing"
            ).format(_MATCHER, input_field, _MATCHED_SHIM_PAYLOAD_LIMIT_BYTES),
            file=_sys.stderr,
        )
        return 2
    _sys.stdin = _io.TextIOWrapper(_io.BytesIO(replay), encoding="utf-8")
    try:
        rc = _original_main(replay)
    except SystemExit as exc:
        return _shim_exit_code(exc)
    if rc is None:
        return 0
    return int(rc)


def _shim_dispatch_selections(payload):
    try:
        yield from _shim_select_payloads(payload)
    except Exception as exc:
        print(
            "matcher-shim [{}]: dispatch error: {}".format(_MATCHER, exc),
            file=_sys.stderr,
        )
        _sys.exit(2)


def _shim_debug_trace(fire):
    if not _os.environ.get("COPILOT_HOOK_DEBUG"):
        return
    kind, _ = _shim_classify(_MATCHER)
    _sys.stderr.write(
        "matcher-shim [{}]: kind={} fired={}\n".format(_MATCHER, kind, fire)
    )


def _shim_dispatch():
    try:
        _raw = _sys.stdin.buffer.read(_HOOK_STDIN_CEILING_BYTES + 1)
    except Exception as exc:  # pragma: no cover - defensive
        print(
            "matcher-shim [{}]: failed to buffer stdin: {}".format(_MATCHER, exc),
            file=_sys.stderr,
        )
        _sys.exit(2)
    if len(_raw) > _HOOK_STDIN_CEILING_BYTES:
        print(
            "matcher-shim [{}]: stdin exceeds {} bytes; refusing".format(
                _MATCHER, _HOOK_STDIN_CEILING_BYTES
            ),
            file=_sys.stderr,
        )
        _sys.exit(2)
    try:
        payload = _shim_load_json(_raw or b"{}")
    except RecursionError:
        # Deeply nested JSON exhausts the parser recursion budget and raises
        # RecursionError, which is NOT a ValueError subclass, so it would
        # otherwise escape the malformed-JSON handler below, print a traceback,
        # and exit 1. A standalone shim (run directly, not under the dispatcher)
        # must fail closed the same way the dispatcher does: bounded diagnostic
        # (no traceback, no payload bytes) and exit 2 (issue #3169).
        print(
            "matcher-shim [{}]: stdin JSON nesting too deep; refusing".format(
                _MATCHER
            ),
            file=_sys.stderr,
        )
        _sys.exit(2)
    except ValueError as exc:
        print(
            "matcher-shim [{}]: malformed JSON on stdin: {}".format(_MATCHER, exc),
            file=_sys.stderr,
        )
        _sys.exit(2)
    fire = False
    for selection in _shim_dispatch_selections(payload):
        if not fire:
            fire = True
            _shim_debug_trace(fire)
        rc = _shim_invoke_selection(payload, selection, _raw)
        if rc != 0:
            _sys.exit(rc)
    if not fire:
        _shim_debug_trace(fire)
    _sys.exit(0)
# END MATCHER SHIM

def _original_main(stdin_bytes):
    # original script body begins below
    #!/usr/bin/env python3
    """Block git push when hook generator output drifts from canonical source.

    Alt B (deterministic full-tree regeneration + drift gate) was already
    shipped at CI level via build/scripts/build_all.py --check inside
    .github/workflows/validate-generated-agents.yml. That gate catches the
    "edited a canonical .claude/hooks/<Event>/*.py without regenerating the
    matcher shims under src/copilot-cli/hooks/<event>/" class of bug.

    This guard adds the same check at git-push time so the feedback loop
    moves from CI (minutes) to local terminal (seconds). Activates when
    the push touches a canonical hook source, the Claude settings.json, or
    a generated shim file. Then runs the generator and compares the
    resulting file-system state to detect drift on hook paths.

    Why not call build_all.py --check directly?
        build_all.py --check runs all generators (rules, agents, skills,
        commands, lib, hooks). Total: ~0.2s. For a pre-push hook we want
        fast feedback. This guard scopes to hook-related diff only and
        fail-opens on infrastructure errors (build tree absent, generator
        raises) so consumer-repo checkouts are not blocked.

    Hook Type: PreToolUse
    Exit Codes (Claude Hook Semantics, exempt from ADR-035):
        0 = Allow (no hook-shim drift detected, or diff did not touch hook paths)
        2 = Block (drift detected; the message lists drifted shim paths)

    Fail-open path:
        Build tree absent (consumer-repo checkout), generator module
        unimportable, or generator raises unexpectedly: emit a fail-open
        EVENT line for telemetry and allow the push. Real drift always
        blocks; only infrastructure failures fail-open.

    Refs: ADR-061 (Withdrawn 2026-05-27); .agents/critique/ADR-061-debate-log.md
    """


    import importlib.util
    import io
    import shutil
    import subprocess
    import sys
    from contextlib import redirect_stderr, redirect_stdout
    from pathlib import Path

    from _bootstrap import ensure_plugin_paths

    ensure_plugin_paths()

    from hook_utilities import get_project_directory  # noqa: E402
    from push_guard_base import emit_fail_open, run_guard  # noqa: E402

    GUARD_NAME = "hook-drift"


    def _emit_k1(detail: str) -> None:
        """Record a K1 kill-criteria event for this drift-guard block.

        K1 (REQ-008-09) counts drift-hook blocks so a maintainer can tell
        when the canonical contract is too strict (3+ false positives in 30
        days rolls back the convergence design). The drift-guard block is the
        raw K1 signal; classifying a block as a true vs false positive happens
        later at read time.

        Telemetry must never block a push: any failure to load or call the
        emitter is swallowed and surfaced as a fail-open EVENT line, never
        raised. The emitter lives outside the plugin lib
        (``scripts/metrics/kill_criteria.py``) and is loaded by file path from
        the project root.
        """
        try:
            project_dir = get_project_directory()
            emitter_path = Path(project_dir) / "scripts" / "metrics" / "kill_criteria.py"
            if not emitter_path.is_file():
                emit_fail_open(GUARD_NAME, "k1_emitter_missing", str(emitter_path))
                return
            spec = importlib.util.spec_from_file_location("kill_criteria", emitter_path)
            if spec is None or spec.loader is None:
                emit_fail_open(GUARD_NAME, "k1_emitter_unloadable", str(emitter_path))
                return
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            module.emit_event("K1", detail)
        except Exception as exc:  # pragma: no cover - defensive fail-open
            emit_fail_open(GUARD_NAME, "k1_emit_failed", f"{type(exc).__name__}: {exc}")

    # Globs that wake this guard. A push that touches any of these has a
    # non-trivial chance of causing hook-shim drift. The validator itself
    # decides whether drift actually exists.
    _GLOBS = (
        ".claude/hooks/*.py",
        ".claude/hooks/**/*.py",
        ".claude/settings.json",
        "src/copilot-cli/hooks/*.py",
        "src/copilot-cli/hooks/**/*.py",
    )


    def _import_generator():
        """Import generate_hooks from the repo's build tree.

        Returns ``(module, config_path, repo_root)`` on success, or
        ``None`` on any infrastructure failure (build tree absent,
        import failure). Every failure path emits a fail-open EVENT so
        telemetry surfaces the degraded state.
        """
        project_dir = get_project_directory()
        if not project_dir:
            emit_fail_open(
                GUARD_NAME,
                "no_project_dir",
                "get_project_directory returned empty; cannot locate build tree",
            )
            return None
        repo_root = Path(project_dir)
        candidate = repo_root / "build" / "scripts"
        if not candidate.is_dir():
            emit_fail_open(
                GUARD_NAME,
                "build_tree_absent",
                f"build/scripts not found under {project_dir}; consumer-repo checkout",
            )
            return None
        config_path = repo_root / "templates" / "platforms" / "copilot-cli.yaml"
        if not config_path.is_file():
            emit_fail_open(
                GUARD_NAME,
                "config_missing",
                f"copilot-cli.yaml not found at {config_path}",
            )
            return None
        if str(candidate) not in sys.path:
            sys.path.insert(0, str(candidate))
        try:
            import generate_hooks as gh  # noqa: PLC0415
        except ImportError as exc:
            emit_fail_open(
                GUARD_NAME,
                "import_failed",
                f"generate_hooks: {type(exc).__name__}: {exc}",
            )
            return None
        return gh, config_path, repo_root


    def _hook_diff_paths(repo_root: Path) -> list[str]:
        """Return uncommitted paths under src/copilot-cli/hooks/.

        Combines two sources so that both modified tracked files and new
        untracked files (e.g. freshly generated shims) are included:

        1. ``git diff --name-only`` (no HEAD): unstaged working-tree changes
           relative to the index (modified tracked files not yet staged);
           does not mix in committed state.
        2. ``git ls-files --others --exclude-standard src/copilot-cli/hooks/``:
           untracked files that the generator may have created.

        A failure to run git (binary not found, timeout) is treated as
        no-diff and the guard fails open. The calling hook returns 0 so
        that a broken environment does not block every push.
        """
        hook_prefix = "src/copilot-cli/hooks/"
        git_executable = shutil.which("git")
        if not git_executable:
            return []
        try:
            diff_result = subprocess.run(
                [git_executable, "-C", str(repo_root), "diff", "--name-only"],
                capture_output=True,
                text=True,
                check=False,
                timeout=5,
            )
            untracked_result = subprocess.run(
                [
                    git_executable,
                    "-C",
                    str(repo_root),
                    "ls-files",
                    "--others",
                    "--exclude-standard",
                    hook_prefix,
                ],
                capture_output=True,
                text=True,
                check=False,
                timeout=5,
            )
        except (FileNotFoundError, subprocess.TimeoutExpired):
            return []
        paths: list[str] = []
        if diff_result.returncode == 0:
            paths.extend(
                line
                for line in diff_result.stdout.splitlines()
                if line.startswith(hook_prefix)
            )
        if untracked_result.returncode == 0:
            paths.extend(
                line
                for line in untracked_result.stdout.splitlines()
                if line.startswith(hook_prefix)
            )
        return paths


    def _validate(_matching: list[str], _all_changed: list[str]) -> list[str]:
        """Run the hook generator and report any drift on hook paths.

        Approach: snapshot the hook-path diff before running the generator,
        then run generate_hooks.generate_hooks() and snapshot again. Only
        paths that appear in the post-generator snapshot but not the
        pre-existing snapshot are reported. This isolates generator-introduced
        drift from any pre-existing local modifications and prevents false
        positives from unrelated uncommitted changes under src/copilot-cli/hooks/.

        Captures generator stdout/stderr to suppress its verbose audit
        output from the hook's user-facing message.
        """
        imported = _import_generator()
        if imported is None:
            return []
        gh, config_path, repo_root = imported

        # Snapshot pre-existing hook-path changes so they are not attributed
        # to this generator run (false-positive prevention).
        pre_existing = set(_hook_diff_paths(repo_root))

        # Run the generator. Suppress its stdout/stderr; we only care about
        # the resulting file-system state and the subsequent diff.
        try:
            with redirect_stdout(io.StringIO()), redirect_stderr(io.StringIO()):
                rc, _run_result = gh.generate_hooks(config_path, repo_root)
        except Exception as exc:  # pragma: no cover - defensive fail-open
            emit_fail_open(
                GUARD_NAME,
                "generator_raised",
                f"{type(exc).__name__}: {exc}",
            )
            return []

        if rc != 0:
            emit_fail_open(
                GUARD_NAME,
                "generator_failed",
                f"generate_hooks returned non-zero: {rc}",
            )
            return []

        post_run = set(_hook_diff_paths(repo_root))
        drifted = sorted(post_run - pre_existing)
        if not drifted:
            return []

        _emit_k1(",".join(drifted))

        out: list[str] = [
            "Hook-shim drift detected (canonical edited without regenerating shims):",
        ]
        for path in drifted:
            out.append(f"  {path}")
        out.append("")
        out.append(
            "Fix: run `python3 build/scripts/build_all.py` to regenerate, then "
            "stage the resulting changes under src/copilot-cli/hooks/ and push "
            "again. The CI staleness gate (validate-generated-agents.yml) "
            "fires on the same condition; this guard catches it locally."
        )
        out.append(
            "Background: ADR-061 (withdrawn 2026-05-27) proposed a structural "
            "fix (delegate-shim). The 6-agent debate concluded that this "
            "drift gate at the procedural layer is sufficient until "
            "multi-matcher hook count exceeds 8 (current: 4). See "
            ".agents/critique/ADR-061-debate-log.md."
        )
        return out


    def main() -> int:
        return run_guard(_validate, list(_GLOBS), GUARD_NAME, include_deletions=False)
    return main()

_shim_dispatch()
